    def count_independent_sets(m):
        G = nx.Graph()
        for i in range(1, 2*m + 1):
            G.add_node(i)
        for i in range(1, 2*m):
            G.add_edge(i, i + 1)
        for i in range(1, m + 1):
            G.add_edge(i, i + m)

        count = 0
        nodes = list(G.nodes())
        for i in range(len(nodes) + 1):
            for subset in itertools.combinations(nodes, i):
                is_independent = True
                for u, v in itertools.combinations(subset, 2):
                    if G.has_edge(u, v):
                        is_independent = False
                        break
                if is_independent:
                    count += 1
        return count

    return [count_independent_sets(m) for m in range(1, limit + 1)]

